        return new Source("{% extends 'base.html.twig' %}

{% block title %}Cập nhật mã sinh viên{% endblock %}

{% block body %}
    <div class=\"container my-5\">
        <div class=\"row justify-content-center\">
            <div class=\"col-md-6\">
                <div class=\"card\">
                    <div class=\"card-header bg-primary text-white\">
                        <h4 class=\"mb-0\">Cập nhật mã sinh viên</h4>
                    </div>
                    <div class=\"card-body\">
                        {% for message in app.flashes('success') %}
                            <div class=\"alert alert-success\">{{ message }}</div>
                        {% endfor %}

                        {% for message in app.flashes('error') %}
                            <div class=\"alert alert-danger\">{{ message }}</div>
                        {% endfor %}

                        <p>Chào {{ app.user.name }}, bạn cần cập nhật mã sinh viên để tiếp tục sử dụng hệ thống.</p>
                        <p>Mã sinh viên hiện tại: <strong>{{ app.user.studentId }}</strong></p>

                        {{ form_start(form) }}
                            {{ form_row(form.student_id) }}
                            <button type=\"submit\" class=\"btn btn-primary\">Cập nhật</button>
                        {{ form_end(form) }}
                    </div>
                </div>
            </div>
        </div>
    </div>
{% endblock %}", "security/update_student_id.html.twig", "C:\\laragon\\www\\BookClub_MS\\templates\\security\\update_student_id.html.twig");
